const N = 1000, PRIMERA_MALA = 637;
let pruebas = 0;
const anda = (v) => { pruebas++; return v < PRIMERA_MALA; };
// Sabemos que la versión 1 anda y la 1000 falla. ¿Cuál fue la primera que falló?
let buena = 1, mala = N;
while (mala - buena > 1) {
  const medio = Math.floor((buena + mala) / 2);
  const ok = anda(medio);
  console.log(`prueba ${pruebas}: versión ${medio} ${ok ? "anda" : "FALLA"} -> quedan ${ok ? mala - medio : medio - buena} candidatas`);
  if (ok) buena = medio; else mala = medio;
}
console.log(`La primera versión mala es la ${mala}. Pruebas: ${pruebas}. (log2(1000) = ${Math.log2(N).toFixed(2)})`);

