let stock = 10;
async function reservar(n) {
  const actual = stock;      // lee
  await null;                // acá otra tarea puede colarse
  stock = actual - n;        // escribe con el valor viejo
}
await Promise.all([reservar(3), reservar(4)]);
console.log("Stock final:", stock, "(esperado: 3)");

// Ilustración propia (no es el código de la NASA): dos programas que se pasan un archivo con un impulso
const LBF_A_N = 4.4482216152605;        // 1 libra-fuerza = 4,448… newtons (definición exacta de la libra)

// Programa A (tierra): calcula el impulso de un disparo en libras-fuerza por segundo y lo escribe sin decir la unidad
function escribirArchivo(impulsoLbfS) {
  return { impulso: impulsoLbfS };
}
// Programa B (navegación): el contrato dice que ese número viene en newton-segundo
function leerArchivo(archivo) {
  return archivo.impulso;               // ya en «newton-segundo», según la especificación
}

const real_Ns = 10 * LBF_A_N;           // un disparo real de 10 lbf·s son 44,48 N·s
const archivo = escribirArchivo(10);    // pero A escribe el 10 a secas
const estimado_Ns = leerArchivo(archivo);

console.log("lo que B cree que pasó:", estimado_Ns.toFixed(2), "N·s");
console.log("lo que pasó de verdad: ", real_Ns.toFixed(2), "N·s");
console.log("B subestima por un factor de", (real_Ns / estimado_Ns).toFixed(2));
console.log("fracción del efecto que B no ve:", ((1 - estimado_Ns / real_Ns) * 100).toFixed(1) + " %");

// Una defensa barata: que el dato diga su unidad y que el lector falle rápido si no coincide
function escribirConUnidad(valor, unidad) { return { valor, unidad }; }
function leerImpulsoNs(archivo) {
  if (archivo.unidad !== "N*s") throw new Error(`impulso en «${archivo.unidad}»; el contrato pide «N*s»`);
  return archivo.valor;
}
try {
  leerImpulsoNs(escribirConUnidad(10, "lbf*s"));
} catch (e) {
  console.log("con unidad explícita:", e.message);
}

// Planilla de reparto: peso por destino y pallets que pasan el límite del autoelevador
const pallets = [
  { id: "P1", destino: "Rosario", kg: 420 },
  { id: "P2", destino: "Córdoba", kg: 610 },
  { id: "P3", destino: "Rosario", kg: 380 },
  { id: "P4", destino: "Córdoba", kg: 905 },
  { id: "P5", destino: "Rosario", kg: "1150" },
];
const LIMITE_KG = 1000;

function pesoPorDestino(lista, destino) {
  let total = 0;
  for (let i = 0; i <= lista.length; i++) {
    if (lista[i].destino = destino) total += lista[i].kg;
  }
  return total;
}

function sobreLimite(lista) {
  return lista.filter((p) => p.kg > LIMITE_KG).map((p) => p.id);
}

console.log("Rosario:", pesoPorDestino(pallets, "Rosario"), "kg");
console.log("Córdoba:", pesoPorDestino(pallets, "Córdoba"), "kg");
console.log("Sobre el límite:", sobreLimite(pallets));
